dashboard.definition:
{
  "title": "Wazuh - Office - Panel - Drilldown user config dashboard",
  "description": "Office - Panel - Drilldown user config dashboard of the Wazuh dashboard, on the findings exported from the Wazuh indexer. Pick the user in the User input, as the Wazuh dashboard does.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_scope": {
      "type": "input.dropdown",
      "title": "User",
      "dataSources": {
        "primary": "ds_input_01"
      },
      "options": {
        "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
        "token": "scope",
        "defaultValue": "*"
      },
      "context": {
        "formattedConfig": {
          "number": {
            "prefix": ""
          }
        },
        "formattedStatics": ">statics | formatByType(formattedConfig)",
        "statics": [
          [
            "All"
          ],
          [
            "*"
          ]
        ],
        "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\") | formatByType(formattedConfig)",
        "value": ">primary | seriesByName(\"value\") | renameSeries(\"value\") | formatByType(formattedConfig)"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_input_01": {
      "type": "ds.search",
      "name": "User",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"o365\" \"user.name\"=* | eval value='user.name' | stats count by value | sort - count | head 500 | eval label=value | fields label, value"
      }
    },
    "ds_01": {
      "type": "ds.search",
      "name": "Stats",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"o365\" \"user.name\"=$scope|s$ | stats count as value"
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "viz_02",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"o365\" \"user.name\"=$scope|s$ | eval f1='event.type{}' | stats max(f1) as value"
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "Top Event Actions",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"o365\" \"user.name\"=$scope|s$ | eval f1='event.action' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"event.action\", metric as \"Count\""
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "Client IP operations",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"o365\" \"user.name\"=$scope|s$ | eval f1='client.ip', f2='event.action', f3='event.type{}' | stats count as metric by f1, f2, f3 | sort - metric | head 500 | rename f1 as \"Client IP address\", f2 as \"Action\", f3 as \"Event Type\", metric as \"Count\""
      }
    },
    "ds_05": {
      "type": "ds.search",
      "name": "Office 365 events over time",
      "options": {
        "query": "`wazuh_findings` \"wazuh.integration.name\"=\"o365\" \"user.name\"=$scope|s$ | eval f1='event.type{}' | timechart span=1h useother=f usenull=f limit=5 count by f1"
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.singlevalue",
      "title": "Stats",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {
        "underLabel": "Total Events"
      }
    },
    "viz_02": {
      "type": "splunk.singlevalue",
      "title": "",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {
        "underLabel": "Max event type detected"
      }
    },
    "viz_03": {
      "type": "splunk.pie",
      "title": "Top Event Actions",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_04": {
      "type": "splunk.table",
      "title": "Client IP operations",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {}
    },
    "viz_05": {
      "type": "splunk.line",
      "title": "Office 365 events over time",
      "dataSources": {
        "primary": "ds_05"
      },
      "options": {}
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 516,
      "display": "auto-scale"
    },
    "globalInputs": [
      "input_global_trp",
      "input_scope"
    ],
    "structure": [
      {
        "item": "viz_01",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 171,
          "h": 276
        }
      },
      {
        "item": "viz_02",
        "type": "block",
        "position": {
          "x": 175,
          "y": 0,
          "w": 171,
          "h": 276
        }
      },
      {
        "item": "viz_03",
        "type": "block",
        "position": {
          "x": 350,
          "y": 0,
          "w": 346,
          "h": 276
        }
      },
      {
        "item": "viz_04",
        "type": "block",
        "position": {
          "x": 700,
          "y": 0,
          "w": 496,
          "h": 276
        }
      },
      {
        "item": "viz_05",
        "type": "block",
        "position": {
          "x": 0,
          "y": 280,
          "w": 1196,
          "h": 216
        }
      }
    ]
  }
}
